ALTER TABLE affiliate_discoveries ADD COLUMN "expandedTerms" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "requestedTerm" TEXT, ADD COLUMN "requestedPage" INTEGER, ADD COLUMN "runStartedAt" TIMESTAMP(3), ADD COLUMN "durationMs" INTEGER;
CREATE TABLE affiliate_discovery_pages ("tenantId" TEXT NOT NULL,"segmentId" TEXT NOT NULL,term TEXT NOT NULL,page INTEGER NOT NULL,"productsJson" JSONB NOT NULL,"countsJson" JSONB NOT NULL,total INTEGER NOT NULL,"checkedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("tenantId","segmentId",term,page),FOREIGN KEY("segmentId","tenantId") REFERENCES affiliate_segments(id,"tenantId") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE affiliate_price_observations ("tenantId" TEXT NOT NULL,"itemId" TEXT NOT NULL,day DATE NOT NULL,"priceCents" INTEGER NOT NULL CHECK ("priceCents">0),"observedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("tenantId","itemId",day),FOREIGN KEY("tenantId") REFERENCES tenants(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX affiliate_price_observations_tenant_item_observed_idx ON affiliate_price_observations("tenantId","itemId","observedAt");
CREATE TABLE affiliate_product_decisions ("tenantId" TEXT NOT NULL,"segmentId" TEXT NOT NULL,"itemId" TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN ('DISCARDED','SENT')),reason TEXT NOT NULL,"actorId" TEXT,"broadcastId" TEXT,"priceCents" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,PRIMARY KEY("tenantId","segmentId","itemId"),FOREIGN KEY("segmentId","tenantId") REFERENCES affiliate_segments(id,"tenantId") ON DELETE CASCADE ON UPDATE CASCADE);
